const PRIORITIES = ['low', 'normal', 'high'];

let nextId = 1;

const TOOLS = [
  {
    name: 'ticket_create',
    description: 'Create a new support ticket.',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Short title of the ticket.' },
        description: { type: 'string', description: 'Detailed description of the ticket.' },
        priority: { type: 'string', enum: PRIORITIES, description: 'Priority of the ticket. Defaults to normal.' }
      },
      required: ['title', 'description'],
      additionalProperties: false
    }
  }
];

export async function listTools() {
  return TOOLS;
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

export async function callTool(name, args = {}) {
  if (name !== 'ticket_create') {
    throw new Error('Unknown tool: ' + name);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const title = args.title;
  const description = args.description;
  const priority = args.priority === undefined ? 'normal' : args.priority;

  if (!isNonEmptyString(title)) {
    throw new Error('title is required and must be a non-empty string');
  }
  if (!isNonEmptyString(description)) {
    throw new Error('description is required and must be a non-empty string');
  }
  if (!PRIORITIES.includes(priority)) {
    throw new Error('priority must be one of: ' + PRIORITIES.join(', '));
  }

  const id = 't' + nextId;
  nextId += 1;

  return {
    content: [
      { type: 'text', text: `Created ticket ${id}: "${title}" [${priority}]` }
    ]
  };
}

